        in.nextToken();
        int n = (int) in.nval;
        long[][] points = new long[n][2];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            points[i][0] = (long) in.nval;
            in.nextToken();
            points[i][1] = (long) in.nval;
        }
